package ru.neverland.mintcontracts.orders;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
public final class CooperativeProjectsSmoke {
    static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}static <T>T done(CompletionStage<T> stage)throws Exception{return stage.toCompletableFuture().get(10,TimeUnit.SECONDS);}static void reject(CompletionStage<?> stage,String why)throws Exception{try{done(stage);}catch(ExecutionException expected){check(true,why);return;}throw new AssertionError(why);}static ServerMaterials open(Path p)throws Exception{var db=new ServerMaterials(p);done(db.ready());return db;}static void close(ServerMaterials db)throws Exception{db.close();done(db.closed());}static ServerMaterials.Delivery delivery(String material,int n){return new ServerMaterials.Delivery(UUID.randomUUID(),UUID.randomUUID(),"builder","test_delivery",material,n,100,"COMMON",1);}
    static void contribute(ServerMaterials db,ServerMaterials.Delivery d,String town,String project)throws Exception{done(db.prepare(d));done(db.cooperativeContext(d.id(),d.player(),town,project));done(db.confirm(d.id(),"confirmed persisted fixture receipt"));}
    static long balance(ServerMaterials db,String material)throws Exception{return done(db.balances()).stream().filter(b->b.material().equals(material)).mapToLong(ServerMaterials.Balance::available).findFirst().orElse(0);}
    @SuppressWarnings("unchecked")static Map<String,Long> amounts(Map<String,Object> p,String key){return(Map<String,Long>)p.get(key);}
    public static void main(String[] args)throws Exception{
        Path folder=Files.createTempDirectory("cooperative-projects-");Path file=folder.resolve("stock.db");var db=open(file);UUID a=UUID.randomUUID(),b=UUID.randomUUID();var old=delivery("STONE",10);done(db.prepare(old));done(db.confirm(old.id(),"old delivery before cooperation"));
        done(db.cooperativePlan("spawn","Общий спавн","SERVER","","spawn_builder",5,Map.of("STONE",12L,"OAK_LOG",8L),"admin"));check(amounts(done(db.cooperativeProject("spawn")),"credited").isEmpty(),"historical pooled stock never invents project contribution");reject(db.cooperativeContext(old.id(),old.player(),a.toString(),"spawn"),"confirmed old delivery cannot be attributed retroactively");
        var stone=delivery("STONE",20);contribute(db,stone,a.toString(),"spawn");var wood=delivery("OAK_LOG",8);contribute(db,wood,b.toString(),"spawn");var project=done(db.cooperativeProject("spawn"));check(Boolean.TRUE.equals(project.get("funded"))&&amounts(project,"credited").equals(Map.of("STONE",12L,"OAK_LOG",8L)),"only exact missing resources are reserved per material");check(balance(db,"STONE")==18&&balance(db,"OAK_LOG")==0,"excess plus old supply stays globally available");done(db.confirm(stone.id(),"repeat already confirmed receipt"));check(done(db.cooperativeReceipts(a,1)).size()==1&&balance(db,"STONE")==18,"repeat confirmation adds neither contribution nor stock");
        reject(db.cooperativePlan("spawn","Changed","SERVER","","spawn_builder",5,Map.of("STONE",12L,"OAK_LOG",8L),"admin"),"immutable project conditions cannot change");check(done(db.cooperativeUnlocks(a)).isEmpty(),"fully funded project alone does not grant completion");done(db.cooperativeFinish("spawn",false,"admin","physical server construction reviewed"));check(done(db.cooperativeUnlocks(a)).contains("spawn_builder")&&done(db.cooperativeUnlocks(b)).contains("spawn_builder"),"completed project grants unlock to actual qualifying contributor cities");done(db.cooperativeFinish("spawn",false,"admin","repeat administrative confirmation"));check(done(db.cooperativeHistory("spawn")).size()==2&&balance(db,"STONE")==18,"repeated completion neither consumes twice nor duplicates history");reject(db.cooperativeFinish("spawn",true,"admin","cannot return spent construction"),"spent project cannot be refunded");check(done(db.cooperativeUnlocks(UUID.randomUUID())).isEmpty(),"unrelated or recreated city never inherits contribution");
        done(db.cooperativePlan("harbor","Городская гавань","CITY",a.toString(),"harbor_builder",2,Map.of("STONE",4L),"admin"));contribute(db,delivery("STONE",2),a.toString(),"harbor");contribute(db,delivery("STONE",2),b.toString(),"harbor");done(db.cooperativeFinish("harbor",false,"admin","city harbour reviewed and complete"));check(done(db.cooperativeUnlocks(a)).contains("harbor_builder")&&!done(db.cooperativeUnlocks(b)).contains("harbor_builder"),"city-scope unlock only belongs to qualifying beneficiary, support history stays recorded");
        done(db.cooperativePlan("cancel","Отменяемый","SERVER","","cancel_builder",1,Map.of("STONE",2L),"admin"));var cancelled=delivery("STONE",3);contribute(db,cancelled,a.toString(),"cancel");long before=balance(db,"STONE");done(db.cooperativeFinish("cancel",true,"admin","admin cancelled unbuilt project"));check(balance(db,"STONE")==before+2&&done(db.cooperativeUnlocks(a)).stream().noneMatch("cancel_builder"::equals),"cancel returns only reserved paid goods to server pool without reward");done(db.cooperativeFinish("cancel",true,"admin","repeat neutral cancellation"));check(balance(db,"STONE")==before+2,"cancel is idempotent");
        done(db.cooperativePlan("late","Поздняя поставка","SERVER","","late_builder",1,Map.of("STONE",5L),"admin"));var late=delivery("STONE",5);done(db.prepare(late));done(db.cooperativeContext(late.id(),late.player(),a.toString(),"late"));reject(db.cooperativeContext(late.id(),late.player(),b.toString(),"late"),"intent city attribution is immutable");done(db.cooperativeFinish("late",true,"admin","closed while delivery was pending"));before=balance(db,"STONE");done(db.confirm(late.id(),"receipt confirmed after cancellation"));check(balance(db,"STONE")==before+5&&amounts(done(db.cooperativeProject("late")),"credited").isEmpty(),"pending late delivery credits ordinary stock without losing paid items or false progress");
        done(db.cooperativePlan("many","Много поставок","SERVER","","many_builder",1,Map.of("STONE",3L,"OAK_LOG",5L),"admin"));long pooledStone=balance(db,"STONE"),pooledWood=balance(db,"OAK_LOG");for(int n=0;n<3;n++)contribute(db,delivery("STONE",1),a.toString(),"many");contribute(db,delivery("OAK_LOG",5),b.toString(),"many");done(db.cooperativeFinish("many",true,"admin","cancel several confirmed resource receipts"));check(balance(db,"STONE")==pooledStone+3&&balance(db,"OAK_LOG")==pooledWood+5,"set-based cancel returns all same-material and distinct-material reservations exactly once");
        close(db);db=open(file);check(done(db.cooperativeUnlocks(a)).equals(Set.of("spawn_builder","harbor_builder"))&&done(db.cooperativeProject("spawn")).get("state").equals("COMPLETED"),"real database reopen preserves projects and distinct city unlocks");close(db);
        Path fault=folder.resolve("fault.db");db=open(fault);done(db.cooperativePlan("fault","Проверка записи","SERVER","","fault_builder",1,Map.of("STONE",5L),"admin"));var d=delivery("STONE",5);done(db.prepare(d));done(db.cooperativeContext(d.id(),d.player(),a.toString(),"fault"));try(var c=DriverManager.getConnection("jdbc:sqlite:"+fault);var s=c.createStatement()){s.execute("CREATE TRIGGER fail_coop BEFORE INSERT ON cooperative_contributions BEGIN SELECT RAISE(ABORT,'injected failure'); END");}reject(db.confirm(d.id(),"inventory receipt persisted before fault"),"real SQL fault prevents partial stock/contribution commit");close(db);
        try(var c=DriverManager.getConnection("jdbc:sqlite:"+fault);var s=c.createStatement();var r=s.executeQuery("SELECT (SELECT COUNT(*) FROM balances),(SELECT COUNT(*) FROM allocations),(SELECT state FROM deliveries)")){check(r.next()&&r.getInt(1)==0&&r.getInt(2)==0&&r.getString(3).equals("PREPARED"),"rollback preserves delivery intent and removes both partial stock and reserve");}try(var c=DriverManager.getConnection("jdbc:sqlite:"+fault);var s=c.createStatement()){s.execute("DROP TRIGGER fail_coop");}db=open(fault);done(db.confirm(d.id(),"recovered original saved receipt"));check(balance(db,"STONE")==0&&amounts(done(db.cooperativeProject("fault")),"credited").get("STONE")==5,"repair confirms original receipt once without another source transfer");close(db);
        System.out.println("CooperativeProjectsSmoke PASS "+checks+" checks");
    }
}
